ALTER TABLE work_orders ADD COLUMN customer_id uuid,ADD COLUMN appointment_id uuid,ADD COLUMN job_card_number varchar(100),ADD COLUMN priority varchar(12) NOT NULL DEFAULT 'NORMAL' CHECK(priority IN ('LOW','NORMAL','HIGH','URGENT')),ADD COLUMN service_advisor_id uuid,ADD COLUMN assigned_technician_id uuid,ADD COLUMN registration varchar(32),ADD COLUMN vehicle_model varchar(180),ADD COLUMN check_in_at timestamptz,ADD COLUMN work_started_at timestamptz,ADD COLUMN work_completed_at timestamptz,ADD COLUMN quality_checked_at timestamptz,ADD COLUMN delivered_at timestamptz,ADD COLUMN estimated_completion_at timestamptz,ADD COLUMN development_approval_id uuid;
UPDATE work_orders SET job_card_number='LEGACY-'||upper(replace(id::text,'-',''));
ALTER TABLE work_orders ALTER COLUMN job_card_number SET NOT NULL;
CREATE UNIQUE INDEX job_card_number_unique ON work_orders(tenant_id,job_card_number);
CREATE UNIQUE INDEX job_appointment_unique ON work_orders(tenant_id,appointment_id) WHERE appointment_id IS NOT NULL;
CREATE INDEX assigned_jobs ON work_orders(tenant_id,branch_id,assigned_technician_id,status);
CREATE TABLE job_card_counters(tenant_id uuid NOT NULL,branch_id uuid NOT NULL,next_value bigint NOT NULL,PRIMARY KEY(tenant_id,branch_id));
CREATE TABLE operation_keys(tenant_id uuid NOT NULL,actor_id uuid NOT NULL,request_key varchar(100) NOT NULL,operation varchar(100) NOT NULL,request_hash varchar(64) NOT NULL,resource_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,actor_id,request_key,operation));
CREATE TABLE vehicle_check_ins(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,branch_id uuid NOT NULL,work_order_id uuid NOT NULL,customer_id uuid NOT NULL,vehicle_id uuid NOT NULL,appointment_id uuid,odometer_kilometers bigint NOT NULL CHECK(odometer_kilometers BETWEEN 0 AND 9999999),complaints varchar(2000) NOT NULL,service_requested varchar(1000) NOT NULL,damage_observations varchar(2000),fuel_level integer CHECK(fuel_level BETWEEN 0 AND 100),accessories jsonb NOT NULL,check_in_at timestamptz NOT NULL,service_advisor_id uuid NOT NULL,created_by uuid NOT NULL,request_hash varchar(64) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version bigint NOT NULL DEFAULT 0,UNIQUE(tenant_id,id),UNIQUE(tenant_id,work_order_id),FOREIGN KEY(tenant_id,work_order_id) REFERENCES work_orders(tenant_id,id));
CREATE UNIQUE INDEX check_in_appointment_unique ON vehicle_check_ins(tenant_id,appointment_id) WHERE appointment_id IS NOT NULL;
CREATE TABLE work_order_tasks(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,branch_id uuid NOT NULL,work_order_id uuid NOT NULL,task_description varchar(1000) NOT NULL,task_category varchar(80) NOT NULL,priority varchar(12) NOT NULL CHECK(priority IN ('LOW','NORMAL','HIGH','URGENT')),status varchar(16) NOT NULL CHECK(status IN ('TODO','IN_PROGRESS','BLOCKED','COMPLETED','CANCELLED')),assigned_technician_id uuid,estimated_duration_minutes integer NOT NULL CHECK(estimated_duration_minutes BETWEEN 1 AND 1440),actual_duration_minutes integer CHECK(actual_duration_minutes>=0),started_at timestamptz,completed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version bigint NOT NULL DEFAULT 0,UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,work_order_id) REFERENCES work_orders(tenant_id,id));
CREATE INDEX tasks_workload ON work_order_tasks(tenant_id,branch_id,assigned_technician_id,status);
CREATE TABLE task_history(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,task_id uuid NOT NULL,action varchar(60) NOT NULL,note varchar(1000) NOT NULL,actor_id uuid NOT NULL,correlation_id varchar(64) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,task_id) REFERENCES work_order_tasks(tenant_id,id));
CREATE TABLE technician_assignments(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,branch_id uuid NOT NULL,work_order_id uuid NOT NULL,task_id uuid,previous_technician_id uuid,technician_id uuid NOT NULL,assigned_by uuid NOT NULL,reason varchar(1000) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,work_order_id) REFERENCES work_orders(tenant_id,id));
CREATE TABLE job_notes(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,work_order_id uuid NOT NULL,actor_id uuid NOT NULL,kind varchar(20) NOT NULL CHECK(kind IN ('TECHNICIAN','INSPECTION','ADDITIONAL_WORK')),note varchar(2000) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,work_order_id) REFERENCES work_orders(tenant_id,id));
CREATE TABLE required_parts(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,work_order_id uuid NOT NULL,description varchar(300) NOT NULL,quantity integer NOT NULL CHECK(quantity BETWEEN 1 AND 10000),status varchar(16) NOT NULL CHECK(status IN ('REQUESTED','RECEIVED','USED','CANCELLED')),requested_by uuid NOT NULL,version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,work_order_id) REFERENCES work_orders(tenant_id,id));
CREATE TABLE inspection_templates(id uuid PRIMARY KEY,tenant_id uuid,name varchar(120) NOT NULL,version bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE inspection_items(id uuid PRIMARY KEY,template_id uuid NOT NULL REFERENCES inspection_templates(id),category varchar(80) NOT NULL,item varchar(300) NOT NULL,safety_related boolean NOT NULL DEFAULT false,sort_order integer NOT NULL);
INSERT INTO inspection_templates(id,name) VALUES('00000000-0000-0000-0000-000000000410','General workshop observations — not a certified safety procedure');
INSERT INTO inspection_items(id,template_id,category,item,safety_related,sort_order) SELECT md5(category)::uuid,'00000000-0000-0000-0000-000000000410',category,'Record observed condition',category IN ('Brakes','Tires','Suspension','Steering'),n FROM unnest(ARRAY['Engine','Brakes','Tires','Suspension','Steering','Battery and electrical','Fluids','Lights','Air conditioning','Exterior condition','Interior condition']) WITH ORDINALITY AS x(category,n);
CREATE TABLE inspections(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,branch_id uuid NOT NULL,work_order_id uuid NOT NULL,template_id uuid NOT NULL REFERENCES inspection_templates(id),template_snapshot jsonb NOT NULL,status varchar(20) NOT NULL CHECK(status IN ('DRAFT','REVIEW_REQUIRED','COMPLETED')),inspected_by uuid NOT NULL,reviewed_by uuid,review_notes varchar(1000),completed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version bigint NOT NULL DEFAULT 0,UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,work_order_id) REFERENCES work_orders(tenant_id,id));
CREATE TABLE inspection_findings(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,inspection_id uuid NOT NULL,work_order_id uuid NOT NULL,item_id uuid NOT NULL,category varchar(80) NOT NULL,inspection_item varchar(300) NOT NULL,condition varchar(24) NOT NULL CHECK(condition IN ('GOOD','ATTENTION_REQUIRED','NOT_INSPECTED','NOT_APPLICABLE')),technician_notes varchar(2000) NOT NULL DEFAULT '',severity varchar(12) NOT NULL CHECK(severity IN ('LOW','MEDIUM','HIGH')),requires_attention boolean NOT NULL DEFAULT false,safety_related boolean NOT NULL,photo_references jsonb NOT NULL DEFAULT '[]',inspected_by uuid,inspected_at timestamptz,UNIQUE(inspection_id,item_id),FOREIGN KEY(tenant_id,inspection_id) REFERENCES inspections(tenant_id,id));
CREATE TABLE quality_checks(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,branch_id uuid NOT NULL,work_order_id uuid NOT NULL,reviewer_id uuid NOT NULL,requested_by uuid NOT NULL,status varchar(16) NOT NULL CHECK(status IN ('PENDING','PASSED','FAILED')),checklist jsonb NOT NULL DEFAULT '{}',reviewer_notes varchar(2000),reviewed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version bigint NOT NULL DEFAULT 0,FOREIGN KEY(tenant_id,work_order_id) REFERENCES work_orders(tenant_id,id));
CREATE UNIQUE INDEX one_pending_quality_check ON quality_checks(tenant_id,work_order_id) WHERE status='PENDING';
CREATE TABLE development_approvals(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,work_order_id uuid NOT NULL,decision varchar(16) NOT NULL CHECK(decision IN ('APPROVE','REJECT','REVISE')),kind varchar(40) NOT NULL DEFAULT 'DEVELOPMENT_SIMULATION',reason varchar(1000) NOT NULL,approved_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,work_order_id) REFERENCES work_orders(tenant_id,id));
CREATE TABLE work_order_status_history(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,branch_id uuid NOT NULL,work_order_id uuid NOT NULL,from_status varchar(40),to_status varchar(40) NOT NULL,note varchar(1000) NOT NULL,actor_id uuid NOT NULL,correlation_id varchar(64) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,work_order_id) REFERENCES work_orders(tenant_id,id));
CREATE TABLE work_order_audit_events(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,branch_id uuid NOT NULL,work_order_id uuid NOT NULL,action varchar(80) NOT NULL,target_id uuid NOT NULL,actor_id uuid NOT NULL,note varchar(1000) NOT NULL,outcome varchar(16) NOT NULL DEFAULT 'SUCCESS',correlation_id varchar(64) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,work_order_id) REFERENCES work_orders(tenant_id,id));
CREATE TABLE workshop_photos(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,branch_id uuid NOT NULL,work_order_id uuid NOT NULL,label varchar(40) NOT NULL,file_name varchar(180) NOT NULL,content_type varchar(40) NOT NULL,byte_size bigint NOT NULL CHECK(byte_size BETWEEN 1 AND 10485760),sha256 varchar(64) NOT NULL,object_key text NOT NULL UNIQUE,status varchar(16) NOT NULL CHECK(status IN ('PENDING','AVAILABLE')),expires_at timestamptz NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version bigint NOT NULL DEFAULT 0,UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,work_order_id) REFERENCES work_orders(tenant_id,id));
CREATE INDEX job_audit_order ON work_order_audit_events(tenant_id,work_order_id,created_at,id);
